import crypto from 'crypto';

class InvalidInputError extends Error {
  constructor(message) {
    super(message);
    this.name = 'InvalidInputError';
  }
}

class InvalidTagError extends Error {
  constructor(message) {
    super(message);
    this.name = 'InvalidTagError';
  }
}

class AveroxCrypto {
  constructor(options = {}) {
    this.algorithms = ['aes-256-gcm'];
    this.config = {
      keySize: 32,        // 256-bit keys
      ivSize: 12,         // 96-bit IV for GCM
      tagLength: 16,      // 128-bit auth tag
      ...options
    };
  }

  /**
   * Generate a cryptographically secure 256-bit key
   * @returns {string} Base64-encoded key
   */
  generateKey() {
    try {
      const key = crypto.randomBytes(this.config.keySize);
      return key.toString('base64');
    } catch (error) {
      throw new InvalidInputError(`Key generation failed: ${error.message}`);
    }
  }

  /**
   * Encrypt plaintext using AES-256-GCM with mandatory AAD
   * @param {string} plaintext - Data to encrypt
   * @param {string} key - Base64-encoded 256-bit key
   * @param {string} aad - Additional authenticated data (mandatory)
   * @returns {string} JSON envelope containing encrypted data
   */
  encryptAESGCM(plaintext, key, aad) {
    // Input validation
    if (!plaintext) throw new InvalidInputError('Plaintext is required');
    if (!key) throw new InvalidInputError('Key is required');
    if (!aad) throw new InvalidInputError('AAD is required for enterprise security');
    
    try {
      // Decode key and generate IV
      const keyBuffer = Buffer.from(key, 'base64');
      if (keyBuffer.length !== 32) {
        throw new InvalidInputError('Key must be 256 bits (32 bytes)');
      }
      
      const iv = crypto.randomBytes(this.config.ivSize);
      
      // Create cipher with proper IV
      const cipher = crypto.createCipheriv('aes-256-gcm', keyBuffer, iv);
      cipher.setAAD(Buffer.from(aad, 'utf8'));
      
      // Encrypt data
      let encrypted = cipher.update(plaintext, 'utf8');
      encrypted = Buffer.concat([encrypted, cipher.final()]);
      
      // Get authentication tag
      const tag = cipher.getAuthTag();
      
      // Create canonical envelope
      const envelope = {
        v: 1,                                    // Version
        alg: 'aes-256-gcm',                     // Algorithm
        iv: iv.toString('base64'),              // IV
        ct: encrypted.toString('base64'),       // Ciphertext
        tag: tag.toString('base64')             // Authentication tag
      };
      
      return JSON.stringify(envelope);
      
    } catch (error) {
      if (error instanceof InvalidInputError) throw error;
      throw new InvalidInputError(`Encryption failed: ${error.message}`);
    }
  }

  /**
   * Decrypt AES-256-GCM encrypted data with authentication verification
   * @param {string} envelopeStr - JSON envelope from encryption
   * @param {string} key - Base64-encoded 256-bit key
   * @param {string} aad - Additional authenticated data (must match encryption)
   * @returns {string} Decrypted plaintext
   */
  decryptAESGCM(envelopeStr, key, aad) {
    // Input validation
    if (!envelopeStr) throw new InvalidInputError('Envelope is required');
    if (!key) throw new InvalidInputError('Key is required');
    if (!aad) throw new InvalidInputError('AAD is required for enterprise security');
    
    try {
      // Parse envelope
      const envelope = JSON.parse(envelopeStr);
      
      // Validate envelope structure
      if (!envelope.v || !envelope.alg || !envelope.iv || !envelope.ct || !envelope.tag) {
        throw new InvalidInputError('Invalid envelope format');
      }
      
      if (envelope.alg !== 'aes-256-gcm') {
        throw new InvalidInputError(`Unsupported algorithm: ${envelope.alg}`);
      }
      
      // Decode components
      const keyBuffer = Buffer.from(key, 'base64');
      const iv = Buffer.from(envelope.iv, 'base64');
      const encrypted = Buffer.from(envelope.ct, 'base64');
      const tag = Buffer.from(envelope.tag, 'base64');
      
      // Validate sizes
      if (keyBuffer.length !== 32) {
        throw new InvalidInputError('Key must be 256 bits (32 bytes)');
      }
      if (iv.length !== 12) {
        throw new InvalidInputError('IV must be 96 bits (12 bytes)');
      }
      if (tag.length !== 16) {
        throw new InvalidInputError('Authentication tag must be 128 bits (16 bytes)');
      }
      
      // Create decipher
      const decipher = crypto.createDecipheriv('aes-256-gcm', keyBuffer, iv);
      decipher.setAuthTag(tag);
      decipher.setAAD(Buffer.from(aad, 'utf8'));
      
      // Decrypt and verify
      let decrypted = decipher.update(encrypted);
      decrypted = Buffer.concat([decrypted, decipher.final()]);
      
      return decrypted.toString('utf8');
      
    } catch (error) {
      if (error instanceof InvalidInputError) throw error;
      if (error.message.includes('Unsupported state') || error.message.includes('auth')) {
        throw new InvalidTagError('Authentication tag verification failed - data may be corrupted or tampered');
      }
      throw new InvalidInputError(`Decryption failed: ${error.message}`);
    }
  }

  /**
   * Secure key derivation using PBKDF2 (addresses audit requirements)
   * @param {string} password - Input password
   * @param {string} salt - Base64-encoded salt
   * @param {number} iterations - Number of iterations (default: 100000)
   * @returns {string} Base64-encoded derived key
   */
  deriveKey(password, salt, iterations = 100000) {
    if (!password) throw new InvalidInputError('Password is required');
    if (!salt) throw new InvalidInputError('Salt is required');
    
    try {
      const saltBuffer = Buffer.from(salt, 'base64');
      const derived = crypto.pbkdf2Sync(password, saltBuffer, iterations, 32, 'sha256');
      return derived.toString('base64');
    } catch (error) {
      throw new InvalidInputError(`Key derivation failed: ${error.message}`);
    }
  }
}

// Export helper functions for convenience
export function encrypt(plaintext, key, aad = 'default') {
  const crypto = new AveroxCrypto();
  return crypto.encryptAESGCM(plaintext, key, aad);
}

export function decrypt(envelopeStr, key, aad = 'default') {
  const crypto = new AveroxCrypto();
  return crypto.decryptAESGCM(envelopeStr, key, aad);
}

export function generateKey() {
  const crypto = new AveroxCrypto();
  return crypto.generateKey();
}

export default AveroxCrypto;